(function (root, factory) {
  if (typeof window === 'object') root.ControlPanelFlowEditorSync = factory()
  else if (typeof module === 'object' && module.exports) module.exports = factory()
})(typeof window === 'object' ? window : this, function () {
  const topic = 'notification/runtime-deploy'

  // Node-RED already owns the Flow-changed notification. This listener only
  // reloads the editor page after a newer runtime revision is announced. It
  // must never read, clear, import, or deploy Flow data.
  function createController (hooks) {
    let stopped = false
    let reloading = false

    function request (message) {
      if (stopped || reloading || !message || typeof message.revision !== 'string') return
      const current = hooks.version()
      // A retained notification received during page startup describes the
      // Flow that is already loaded. Ignore it instead of causing a reload.
      if (typeof current !== 'string' || current === message.revision) return
      reloading = true
      hooks.reload()
    }

    return { request, stop: () => { stopped = true } }
  }

  function install (RED, $, host = window) {
    if (RED.__controlPanelFlowSync) return RED.__controlPanelFlowSync
    if (!RED.comms?.subscribe || !RED.nodes?.version || !host.location?.reload) {
      RED.notify('ControlPanel Flow change listener is unavailable in this editor.', 'warning')
      return
    }

    const controller = createController({
      version: () => RED.nodes.version(),
      reload: () => host.location.reload()
    })
    const changed = (_topic, message) => controller.request(message)
    RED.comms.subscribe(topic, changed)
    const instance = {
      request: controller.request,
      dispose () {
        controller.stop()
        RED.comms.unsubscribe(topic, changed)
        delete RED.__controlPanelFlowSync
      }
    }
    RED.__controlPanelFlowSync = instance
    return instance
  }

  return { topic, createController, install }
})
